<div class="page-actions"><a class="back-link" href="<?= isset($row)?site_url('admin/koperasi/'.$row['id']):site_url('admin/koperasi') ?>">← Kembali</a></div><section class="form-panel"><div class="form-intro"><span class="panel-overline">PROFIL KOPERASI</span><h2><?= h($title) ?></h2><p>Isi identitas dari ODS atau dokumen resmi. Wilayah yang belum cocok dapat diperbaiki setelah diperiksa.</p></div><form method="post" action="<?= site_url('admin/koperasi/simpan') ?>"><?= csrf_input() ?><input type="hidden" name="id" value="<?= h($row['id']??'') ?>"><div class="form-grid"><label class="form-full">Nama koperasi <span class="required">*</span><input name="name" value="<?= h($row['name']??'') ?>" required maxlength="255"></label><label>NIK koperasi<input name="nik" value="<?= h($row['nik']??'') ?>" maxlength="40" placeholder="Nomor induk koperasi"></label><label>Nomor badan hukum<input name="legal_number" value="<?= h($row['legal_number']??'') ?>" maxlength="190"></label><label>Jenis koperasi<select name="type_item_id"><option value="">Pilih jenis</option><?php foreach ($types as $x): ?><option value="<?= $x['id'] ?>" <?= (string)($row['type_item_id']??'')===(string)$x['id']?'selected':'' ?>><?= h($x['name']) ?></option><?php endforeach; ?></select></label><label>Bentuk koperasi<select name="form_item_id"><option value="">Pilih bentuk</option><?php foreach ($forms as $x): ?><option value="<?= $x['id'] ?>" <?= (string)($row['form_item_id']??'')===(string)$x['id']?'selected':'' ?>><?= h($x['name']) ?></option><?php endforeach; ?></select></label><label>Pola pengelolaan<select name="pattern_item_id"><option value="">Pilih pola</option><?php foreach ($patterns as $x): ?><option value="<?= $x['id'] ?>" <?= (string)($row['pattern_item_id']??'')===(string)$x['id']?'selected':'' ?>><?= h($x['name']) ?></option><?php endforeach; ?></select></label><label>KUK<select name="kuk_item_id"><option value="">Pilih KUK</option><?php foreach ($kuks as $x): ?><option value="<?= $x['id'] ?>" <?= (string)($row['kuk_item_id']??'')===(string)$x['id']?'selected':'' ?>><?= h($x['name']) ?></option><?php endforeach; ?></select></label><label>Lingkup kewenangan<select name="authority_scope"><option value="kabupaten" <?= ($row['authority_scope']??'kabupaten')==='kabupaten'?'selected':'' ?>>Kabupaten</option><option value="provinsi" <?= ($row['authority_scope']??'')==='provinsi'?'selected':'' ?>>Provinsi · data referensi</option><option value="nasional" <?= ($row['authority_scope']??'')==='nasional'?'selected':'' ?>>Nasional · data referensi</option><option value="belum_ditetapkan" <?= ($row['authority_scope']??'')==='belum_ditetapkan'?'selected':'' ?>>Belum ditetapkan</option></select></label><label>Status ODS<input name="ods_status" value="<?= h($row['ods_status']??'') ?>" placeholder="Aktif / Tidak Aktif"></label><?php $selector_id='cooperative-region';$selector_name='village_id';$selector_until='village';$selector_all_names=true;$this->load->view('regions/selector',compact('selector_id','selector_name','selector_until','selector_all_names','selected_ids','provinces')); ?><label class="form-full">Alamat<textarea name="address" rows="3"><?= h($row['address']??'') ?></textarea></label><label>Email<input name="email" type="email" value="<?= h($row['email']??'') ?>"></label><label>Lintang (latitude)<input name="latitude" type="number" step="0.0000001" min="-90" max="90" value="<?= h($row['latitude']??'') ?>" placeholder="-6.7070000"></label><label>Bujur (longitude)<input name="longitude" type="number" step="0.0000001" min="-180" max="180" value="<?= h($row['longitude']??'') ?>" placeholder="111.3470000"></label></div><div class="form-actions"><button class="button button-dark" type="submit">Simpan koperasi <span>→</span></button><a class="button button-quiet" href="<?= site_url('admin/koperasi') ?>">Batal</a></div></form></section>